vulnerable_code:
app.get('/api/security/:id', async (req, res) => {
  const item = await SecurityPref.findByPk(req.params.id);
  res.json(item);
});

corrected_code:
app.get('/api/security/:id', async (req, res) => {
  const item = await SecurityPref.findOne({ where: { id: req.params.id, userId: req.user.id } });
  if (!item) return res.status(404).send('Not found');
  res.json(item);
});
